function drawGraphics(){C.fit(root);wireNavigation();window.RespHelp.attach(root);const p=selected();if($('#patient-network'))window.RespGraph3D.mount($('#patient-network'),{patients:contextNodes(),edges:currentEdges(),patient:Math.max(0,currentIndex()),compare:contextNodes().findIndex(n=>n.id===S.compare),focus:S.focus,validation:S.validation,lens:S.lens,orbit:S.orbit,onSelect:(i,shift)=>{if(shift){S.compare=contextNodes()[i].id;render();}else choose(contextNodes()[i].id);}});if($('#overview-network')){const nodes=reference(),index=nodes.findIndex(n=>n.id===S.patient);window.RespGraph3D.mount($('#overview-network'),{patients:nodes,edges:D.graph.edges,patient:Math.max(0,index),compare:null,focus:S.focus,validation:S.validation,lens:false,orbit:S.orbit,onSelect:i=>{S.context='reference';choose(nodes[i].id);}});}if($('#evidence-network')){const ex=D.experiments[S.experiment],nodes=reference().map((p,i)=>({...p,p:ex.probabilities[i],mc:undefined}));window.RespGraph3D.mount($('#evidence-network'),{patients:nodes,edges:ex.edges,patient:Math.max(0,nodes.findIndex(n=>n.id===S.patient)),compare:null,focus:S.focus,validation:true,lens:false,orbit:S.orbit,onSelect:i=>{S.patient=nodes[i].id;S.context='reference';S.focus=true;render();}});}if($('#working-network')){const nodes=managed?.nodes||reference(),edges=managed?.edges||D.graph.edges,index=nodes.findIndex(n=>n.id===S.patient);window.RespGraph3D.mount($('#working-network'),{patients:nodes,edges,patient:Math.max(0,index),compare:null,focus:S.focus&&index>=0,validation:S.validation,lens:false,orbit:S.orbit,onSelect:i=>{S.patient=nodes[i].id;S.context=managed?'managed':'reference';S.focus=true;render();}});}if($('#patient-imaging'))window.RespMRI.mount(p.id,S.compare||null);if($('#attention-canvas'))drawMatrix();}
function attentionMatrix(){if(S.context==='managed'&&managed)return managed.attention;if(S.matrixModel<0||!E.attention.models)return E.attention.mean;const heads=E.attention.models[S.matrixModel];return S.matrixHead>=0?heads[S.matrixHead]:heads[0].map((row,i)=>row.map((_,j)=>heads.reduce((sum,h)=>sum+h[i][j],0)/heads.length));}
function drawMatrix(){const c=$('#attention-canvas'),nodes=contextNodes(),n=nodes.length,index=currentIndex();let m=S.context==='managed'&&managed?managed.attention:E.attention.mean;if(S.context==='reference'&&S.matrixModel>=0&&E.attention.models){const heads=E.attention.models[S.matrixModel];m=S.matrixHead>=0?heads[S.matrixHead]:heads[0].map((row,i)=>row.map((_,j)=>heads.reduce((s,h)=>s+h[i][j],0)/heads.length));}const rect=c.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=Math.min(devicePixelRatio||1,1.5);if(w<2||h<2)return;c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const pad=51,size=Math.min(w-pad-6,h-pad-6),cell=size/n,max=Math.max(...m.flat());m.forEach((row,i)=>row.forEach((v,j)=>{const t=v/max;ctx.fillStyle=`rgb(${Math.round(12+35*t)},${Math.round(35+150*t)},${Math.round(58+175*t)})`;ctx.fillRect(pad+j*cell,pad+i*cell,cell-.25,cell-.25);}));ctx.strokeStyle='#f2bd6f';ctx.lineWidth=1.5;ctx.strokeRect(pad,pad+Math.max(0,index)*cell,size,cell);ctx.fillStyle='#b0ccdf';ctx.font='16.5px Microsoft YaHei';for(const i of [...new Set([0,Math.floor(n/4),Math.floor(n/2),Math.floor(3*n/4),n-1])]){ctx.textAlign='center';ctx.fillText(String(i+1).padStart(3,'0'),pad+(i+.5)*cell,24);ctx.textAlign='right';ctx.fillText(String(i+1).padStart(3,'0'),30,pad+(i+.7)*cell);}c.onclick=e=>{const r=c.getBoundingClientRect(),i=Math.floor((e.clientY-r.top-pad)/cell);if(i>=0&&i<n)choose(nodes[i].id);};c.onpointermove=e=>{const r=c.getBoundingClientRect(),i=Math.floor((e.clientY-r.top-pad)/cell),j=Math.floor((e.clientX-r.left-pad)/cell);if(i>=0&&i<n&&j>=0&&j<n)window.RespHelp.show(`${nodes[i].id} 对 ${nodes[j].id} 的关注权重：${(m[i][j]*100).toFixed(4)}%`,e.clientX,e.clientY);};c.onpointerleave=()=>window.RespHelp.hide();}
function wire(){const bind=(id,f)=>{const e=$('#'+id);if(e)e.onclick=f;};const sel=$('#selected-patient');if(sel)sel.onchange=e=>choose(e.target.value);const comp=$('#patient-compare');if(comp)comp.onchange=e=>{S.compare=e.target.value;render();};const context=$('#patient-context');if(context)context.onchange=e=>{S.context=e.target.value;S.patient=contextNodes().find(n=>n.id===S.patient)?.id||contextNodes()[0].id;S.compare='';render();};bind('rotate-graph',()=>{S.orbit=!S.orbit;render();});bind('graph-lens',()=>{S.lens=!S.lens;render();});bind('all-patients',()=>{window.RespGraph3D.reset();S.focus=false;S.compare='';render();});bind('search-patient',()=>{const value=$('#patient-search').value.trim().toUpperCase(),node=contextNodes().find(p=>p.id.toUpperCase()===value||p.id==='EXT-'+value.padStart(3,'0'));if(node)choose(node.id);else toast('未找到该编号的患者');});if($('#patient-search'))$('#patient-search').onkeydown=e=>{if(e.key==='Enter')$('#search-patient').click();};if($('#overview-patient'))$('#overview-patient').onchange=e=>{S.context='reference';choose(e.target.value);};bind('overview-all',()=>{S.focus=false;window.RespGraph3D.reset();render();});bind('overview-focus',()=>{S.focus=true;render();});bind('spread-toggle',()=>{S.spread=!S.spread;render();});bind('heat-prev',()=>{S.heatPage--;render();});bind('heat-next',()=>{S.heatPage++;render();});$$('[data-stable]').forEach(b=>b.onclick=()=>{S.patient=b.dataset.stable;render();});bind('table-prev',()=>{S.tablePage--;render();});bind('table-next',()=>{S.tablePage++;render();});bind('run-working',()=>runWorking());bind('run-working-list',()=>runWorking());bind('restore-working',()=>{removed=[];save();runWorking();});$$('[data-include]').forEach(box=>box.onchange=()=>{const id=box.dataset.include;if(box.checked)removed=removed.filter(x=>x!==id);else if(!removed.includes(id))removed.push(id);save();$('#workspace-status').textContent='工作队列已编辑 · 点击计算当前队列更新预测';});$$('[data-managed-report]').forEach(b=>b.onclick=()=>openManaged(b.dataset.managedReport,'report'));$$('[data-managed-patient]').forEach(b=>b.onclick=()=>openManaged(b.dataset.managedPatient,'image'));$$('[data-edit]').forEach(b=>b.onclick=()=>editRecord(b.dataset.edit));$$('[data-entry-mode]').forEach(b=>b.onclick=()=>{captureDraft();S.entryMode=b.dataset.entryMode;entryDraft=null;render();});bind('load-example',loadExample);bind('clear-entry',()=>{entryDraft={};S.editId=null;render();});bind('save-and-predict',saveEntry);bind('calculate-sensitivity',calculateSensitivity);bind('import-patients',()=>$('#patient-file').click());if($('#patient-file'))$('#patient-file').onchange=e=>importPatients(e.target.files[0]);bind('download-template',()=>download('患者变化率录入模板.csv','text/csv;charset=utf-8','\ufeff'+['patient_id,input_mode,'+Object.keys(metricNames).flatMap(k=>[k+'_pch_T0_T1',k+'_pch_T0_T2']).join(','),'NEW-示例,changes,'+Object.keys(metricNames).flatMap(k=>[I.example.changes[k+'_pch_T0_T1'],I.example.changes[k+'_pch_T0_T2']]).join(',')].join('\r\n')));bind('export-patients',exportPatients);bind('download-report',()=>exportReport(false));bind('print-patient-report',()=>exportReport(true));if($('#matrix-model'))$('#matrix-model').onchange=async e=>{const model=Number(e.target.value);if(model>=0&&!E.attention.models){e.target.disabled=true;try{await window.RespAssets.load('attention');}catch{toast('注意力详情载入失败，请重新选择');e.target.disabled=false;return;}}S.matrixModel=model;S.matrixHead=-1;if(S.page==='patient'&&currentView()==='attention')render();};if($('#matrix-head'))$('#matrix-head').onchange=e=>{S.matrixHead=Number(e.target.value);render();};if(S.page==='boundary'){window.RespArchitecture.wire();bind('data-methods',showMethods);const detail=$('.architecture-panel details');if(detail)detail.ontoggle=()=>{if(detail.open){detail.open=false;showOriginalArchitecture();}};}}
function openManaged(id,view){if(managed?.nodes.some(n=>n.id===id)){S.context='managed';S.patient=id;S.compare='';go('patient',view);}else if(D.patients.some(n=>n.id===id)){S.context='reference';S.patient=id;S.compare='';go('patient',view);}else toast('该患者尚未计算，请先更新工作队列');}
function updateProgress(p){progress=p.stage+' '+p.value+' / '+p.total;$('#workspace-status').textContent=progress;for(const id of ['run-working','run-working-list','save-and-predict','calculate-sensitivity']){const b=$('#'+id);if(b&&busy)b.textContent=progress;}}
async function runWorking(reportId=null){if(busy)return;const nodes=working();if(!nodes.length||nodes.length>200){toast('工作队列人数需在1至200之间');return;}busy=true;progress='准备模型';render();try{const result=await window.RespInference.run(nodes.map(p=>p.features),updateProgress);const predicted=nodes.map((p,i)=>({...p,p:result.probabilities[i],fold_probabilities:result.folds.map(f=>f[i]),delta:p.original_index===null?null:result.probabilities[i]-D.patients[p.original_index].p}));managed={nodes:predicted,edges:result.edges,similarities:result.similarities,attention:result.attention,updated:new Date().toISOString(),signature:JSON.stringify(nodes.map(n=>[n.id,n.features]))};for(const r of records){const p=predicted.find(n=>n.id===r.id);if(p){r.p=p.p;r.fold_probabilities=p.fold_probabilities;r.updated=managed.updated;r.context_n=nodes.length;}}save();S.patient=reportId||predicted.find(p=>p.original_index===null)?.id||predicted[0].id;S.context='managed';S.focus=!!reportId;toast('队列预测完成 · '+nodes.length+'位患者 · '+result.elapsed.toFixed(2)+'秒');if(reportId){S.views.patient='report';S.page='patient';history.pushState(null,'','#patient');}}catch(e){toast(e.message);}finally{busy=false;progress='';render();}}
function captureDraft(){if(S.page!=='sandbox'||currentView()!=='entry'||!$('#new-patient-id'))return;entryDraft={id:$('#new-patient-id').value};$$('[data-entry]').forEach(e=>entryDraft[e.dataset.entry]=e.value);}
function loadExample(){entryDraft={};if(S.entryMode==='features')Object.assign(entryDraft,I.example.features);else if(S.entryMode==='changes')Object.assign(entryDraft,I.example.changes);else Object.entries(I.example.measurements).forEach(([k,values])=>values.forEach((v,t)=>entryDraft[k+'_T'+t]=v));entryDraft.id='';S.editId=null;render();}
function editRecord(id){const r=records.find(r=>r.id===id);if(!r){toast('参考病例的检查记录保持原始数据');return;}S.editId=id;S.entryMode='changes';entryDraft={id,...window.RespInference.changesFromFeatures(r.features)};go('sandbox','entry');}
function uniqueId(id,existing=records){if(id){if(!/^[\p{L}\p{N}_. -]{1,40}$/u.test(id))throw Error('编号请使用文字、数字、空格、下划线或短横线');if(D.patients.some(p=>p.id===id)||existing.some(r=>r.id===id&&r.id!==S.editId))throw Error('患者编号已存在，请使用新的编号');return id;}let i=1;while(existing.some(r=>r.id==='NEW-'+String(i).padStart(3,'0')))i++;return 'NEW-'+String(i).padStart(3,'0');}
function inputRecord(id,mode,values,label=null){let features,changes,measurements;if(mode==='features'){features=Object.fromEntries(I.features.map(f=>{const value=values[f];if(!Number.isFinite(value)||Math.abs(value)>=1e6)throw Error('请填写全部12项有效预处理特征');return [f,value];}));changes=window.RespInference.changesFromFeatures(features);}else if(mode==='measurements'){measurements=Object.fromEntries(Object.keys(metricNames).map(k=>[k,[0,1,2].map(t=>values[k+'_T'+t])]));({features,changes}=window.RespInference.fromMeasurements(measurements));}else{changes=Object.fromEntries(Object.keys(metricNames).flatMap(k=>[1,2].map(t=>{const f=k+'_pch_T0_T'+t,value=values[f];if(!Number.isFinite(value)||value< -100)throw Error('变化率需完整且不小于−100%');return [f,value];})));features=window.RespInference.fromChanges(changes);}return {id,label,features,trajectories:Object.fromEntries(Object.keys(metricNames).map(k=>[k,[0,changes[k+'_pch_T0_T1'],changes[k+'_pch_T0_T2']]])),measurements,created:new Date().toISOString(),source:'manual'};}
async function saveEntry(){captureDraft();try{if(!S.editId&&records.length>=162)throw Error('最多保存162位自定义患者');const values={};for(const e of $$('[data-entry]')){if(!e.value.trim())throw Error('请填写全部检查指标');values[e.dataset.entry]=Number(e.value);}const id=uniqueId($('#new-patient-id').value.trim()),label=$('#new-patient-label').value===''?null:Number($('#new-patient-label').value),record=inputRecord(id,S.entryMode,values,label);if(S.editId){const at=records.findIndex(r=>r.id===S.editId);record.created=records[at].created;records[at]=record;}else records.push(record);removed=removed.filter(x=>x!==id);S.editId=null;entryDraft=null;save();await runWorking(id);}catch(e){const out=$('#entry-error');if(out)out.textContent=e.message;else toast(e.message);}}
async function calculateSensitivity(){if(busy||!managed)return;const p=selected(),index=managed.nodes.findIndex(n=>n.id===p.id),key=JSON.stringify(managed.nodes.map(n=>[n.id,n.p]))+p.id;busy=true;progress='计算指标敏感性';render();try{const r=await window.RespInference.run(managed.nodes.map(p=>p.features),updateProgress,{mode:'sensitivity',patient:index});sensitivityCache.set(key,r.explanations);}catch(e){toast(e.message);}finally{busy=false;render();}}
function download(name,type,body){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function parseCSV(text){let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x.trim()))rows.push(row);row=[];value='';}else value+=c;}if(value||row.length){row.push(value);rows.push(row);}if(quoted)throw Error('CSV引号未闭合');const headers=(rows.shift()||[]).map(x=>x.trim().replace(/^\ufeff/,''));return rows.filter(r=>r.some(x=>x.trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]?.trim()??''])));}
async function importPatients(file){if(!file||busy)return;try{const text=await file.text(),input=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text),rows=Array.isArray(input)?input:input.patients;if(!Array.isArray(rows)||!rows.length)throw Error('未发现患者记录');if(records.length+rows.length>162)throw Error('最多保存162位自定义患者');const staged=[];for(const row of rows){const mode=row.input_mode||row.mode||'changes';if(!['changes','measurements','features'].includes(mode))throw Error('录入模式应为changes、measurements或features');const values={};for(const [k,v] of Object.entries(row.values||row.features||row)){if(!['patient_id','id','input_mode','mode','pCR','label'].includes(k))values[k]=v===''?NaN:Number(v);}const id=uniqueId(String(row.patient_id||row.id||'').trim(),[...records,...staged]),label=(row.pCR??row.label)===''||(row.pCR??row.label)===undefined?null:Number(row.pCR??row.label);if(label!==null&&label!==0&&label!==1)throw Error('病理标签应为0、1或留空');staged.push(inputRecord(id,mode,values,label));}records.push(...staged);save();toast('已导入'+staged.length+'位患者');await runWorking(staged.at(-1).id);}catch(e){toast('导入未完成：'+e.message);}}
function exportPatients(){const fields=['patient_id','input_mode',...I.features,'predicted_pCR','pCR','created'],quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('影见疗效_我的患者.csv','text/csv;charset=utf-8','\ufeff'+[fields.join(','),...records.map(r=>[r.id,'features',...I.features.map(f=>r.features[f]),r.p??'',r.label??'',r.created].map(quote).join(','))].join('\r\n'));}
function reportDocument(){const p=selected(),content=$('#patient-report').innerHTML;return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>${esc(p.id)} · 患者治疗响应分析报告</title><style>body{font:15px/1.6 'Microsoft YaHei',sans-serif;background:#fff;color:#172a40;margin:24px}h1{font-size:25px;margin:0}header{border-bottom:3px solid #2481a7;padding-bottom:15px;margin-bottom:18px}header p{margin:5px 0}.report-print-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.d-panel{border:1px solid #bed2df;border-radius:10px;padding:15px;break-inside:avoid}.d-panel-head{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #dce5ec;margin-bottom:10px}.d-panel-head h2{font-size:18px;margin:0 0 8px}.d-panel-head>span,.d-note{color:#61788b;font-size:12px}.d-viz svg{display:block;width:100%;height:auto;max-height:330px}svg text{font:14px 'Microsoft YaHei',sans-serif;fill:#26485f}.v-grid{stroke:#d5e0e8;fill:none;stroke-dasharray:3 5}.v-axis{stroke:#768d9e;fill:none}.v-value{fill:#1d718e}.v-ring-value{font-size:33px;font-weight:600}.v-stamp{font-size:18px}.d-trajectories{display:grid;grid-template-columns:1fr 1fr;gap:8px}.d-trajectories h3{font-size:13px;margin:0;display:flex;gap:8px}.d-trajectories strong{margin-left:auto}.d-trajectories svg{max-height:160px}.d-legend{display:flex;gap:12px;font-size:11px}.d-legend i{display:inline-block;background:#48c9ef;width:12px;height:3px;margin-right:5px}.d-legend .amber{background:#f2ab62}.report-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px}.report-facts span{display:flex;justify-content:space-between;border-bottom:1px solid #e3ebf0}.report-facts b{color:#176e92}.d-neighbors button{border:0;border-bottom:1px solid #dce4ea;background:none;display:flex;justify-content:space-between;align-items:center;width:100%;padding:10px;color:#183b54;font-size:14px}.d-neighbors small{display:block;color:#718697}.neighbor-track{display:none}.report-response-list>div{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #dce4ea}.d-note{margin-top:8px}button{cursor:default}.report-score svg{max-height:205px}@page{size:A4;margin:12mm}@media print{body{margin:0;font-size:12px}.d-panel{padding:10px}.d-panel-head h2{font-size:15px}.report-print-grid{gap:10px}.d-viz svg{max-height:230px}.d-trajectories svg{max-height:130px}} </style></head><body><header><h1>影见疗效 · 患者治疗响应分析报告</h1><p>患者 ${esc(p.id)} · ${contextNodes().length}人队列 · ${new Date(managed?.updated||Date.now()).toLocaleString('zh-CN')}</p><p>预测pCR概率 ${pct(p.p)} · 十模型原始概率均值</p></header><div class="report-print-grid">${content}</div></body></html>`;}
function exportReport(print){const html=reportDocument(),id=selected().id.replace(/[<>:"/\\|?*]/g,'_');if(!print){download('影见疗效_'+id+'_个性化报告.html','text/html;charset=utf-8',html);return;}const frame=document.createElement('iframe');frame.style.cssText='position:fixed;right:0;bottom:0;width:1px;height:1px;border:0';frame.srcdoc=html;frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print();};document.body.append(frame);setTimeout(()=>frame.remove(),120000);}
function showDialog(title,body){const layer=$('#dialog-layer');layer.hidden=false;layer.innerHTML=`<div class="d-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="d-dialog-head"><h2>${title}</h2><button id="dialog-close">关闭 ×</button></div><div class="d-dialog-body">${body}</div></div>`;$('#dialog-close').onclick=()=>layer.hidden=true;layer.onclick=e=>{if(e.target===layer)layer.hidden=true;};$('#dialog-close').focus();}
function showOriginalArchitecture(){showDialog('论文原始模型架构',`<div class="paper-architecture"><img src="figures/model-architecture.png" alt="论文模型架构"><img src="figures/attention-architecture.png" alt="论文多头自注意力结构"></div>`);}
function showMethods(){showDialog('数据与模型计算记录',`<div class="method-records"><section><h3>患者与影像</h3><p>I-SPY 2开发队列132例；I-SPY 1外部队列38例。匿名MRI影像展示使用首次访视；纵向曲线使用T0、T1、T2定量指标。</p></section><section><h3>浏览器模型</h3><p>十个已训练检查点参数按需载入，沿用原特征顺序、预处理参数、GCN边权归一化、多头注意力和Softmax输出。各模型原始pCR概率取均值。</p></section><section><h3>响应关系</h3><p>构图使用12项响应特征，在当前队列内标准化后计算余弦相似度。外部推理阈值0.8、Top-2，低相似度补充边过滤值0.3。</p></section><section><h3>外部验证与解释</h3><p>AUC 0.8304；ROC、混淆矩阵、原始概率校准图、400组队列重复实验。38例参考患者保留真实SHAP结果；工作队列可计算逐项输入敏感性与跨患者注意力。</p></section><a href="data.json" download>下载完整展示数据 ↗</a><a href="explain-data.json" download>下载外部解释数据 ↗</a></div>`);}
function adaptPanes(){const narrow=innerWidth<1050||innerHeight<650;document.body.dataset.compact=String(narrow);document.body.dataset.short=String(innerHeight<850);const grid=$('.d-grid',root);if(!narrow||!grid)return;const cards=[...grid.children].flatMap(card=>innerWidth<700&&card.classList.contains('d-stack')?[...card.children]:[card]);if(innerWidth<700)grid.replaceChildren(...cards);if(cards.length<2)return;S.mobilePane=Math.min(S.mobilePane,cards.length-1);const nav=document.createElement('div');nav.className='d-pane-nav';nav.innerHTML=cards.map((card,i)=>`<button data-pane="${i}" aria-pressed="${i===S.mobilePane}">${esc(card.querySelector('h2')?.textContent||'分区'+(i+1))}</button>`).join('');grid.before(nav);grid.classList.add('d-paged-grid');cards.forEach((card,i)=>card.classList.toggle('pane-hidden',i!==S.mobilePane));nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{S.mobilePane=Number(b.dataset.pane);cards.forEach((card,i)=>card.classList.toggle('pane-hidden',i!==S.mobilePane));nav.querySelectorAll('button').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===S.mobilePane)));requestAnimationFrame(drawGraphics);});}
function viewTip(page,id){const tips={overview:'疾病亚型与治疗评估目标，配合真实MRI和外部患者结局',journey:'按治疗前、早期、中期和手术后顺序阅读检查与结局',network:'用患者关系网络串联纵向检查、局部聚合与模型预测',insights:'集中查看SHAP贡献、ROC和实际分类结果',space:'依据实际患者相似关系形成的三维网络',image:'浏览真实MRI、分割轮廓和四类检查变化',local:S.context==='managed'?'保持当前关系图，改变一项输入并比较预测变化':'拆分当前预测中各项指标相对参考输入的贡献',global:'38位参考患者的SHAP分布和指标贡献排序',attention:'查看模型对队列中各患者分配的关注权重',report:'汇总当前患者的概率、检查变化、相似病例和十模型输出',summary:'独立外部队列的ROC、混淆矩阵和图结构对照',calibration:'比较平均预测概率与实际pCR比例，并核对逐患者预测',stability:'改变参与计算的患者组合，观察AUC与单患者概率波动',cohort:'当前工作队列的关系网络、预测结果和分类统计',entry:'自行输入检查数据，自动转换特征并运行网页端模型',list:'分组浏览患者，选择加入或移出当前计算队列'};return tips[id]||'点击切换当前页面的分析视图';}
